insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$evm-checkpoint$x$, $x$tool$x$, $x$milestone$x$, $x$ch4$x$, 4, $x$intermediate$x$, 15, 45,
  $x$القيمة المكتسبة عند المعلم$x$,
  $x$اقرأ أداء مشروع عند معلمه بالقيمة المكتسبة: ماذا تقول المؤشرات، وأي تقدير للتكلفة النهائية يصلح، وما القرار الذي يستحقه.$x$,
  $x${"story_ar":"وصل المشروع إلى معلم منتصف التنفيذ. الميزانية عند الإكمال 10 ملايين ريال. المخطط إنجازه حتى اليوم بقيمة 5 ملايين، والمنجز فعلًا يساوي 4 ملايين من الميزانية، والمصروف الفعلي 5 ملايين. اللجنة تجتمع غدًا.","role_ar":"مدير مشروع منصة الخدمات الموحدة","closing_ar":"المؤشر لا يقرر، بل يطرح السؤال الصحيح عند المعلم. وصيغة التقدير تتبع فهمك لسبب الانحراف: متكرر أم عارض.","meters":[],"steps":[{"type":"match","title_ar":"لغة القيمة المكتسبة","prompt_ar":"طابق كل رقم من قصة المشروع بمصطلحه.","context_ar":"","why_ar":"القيمة المكتسبة تقيس الإنجاز بلغة الميزانية، فتقارنه بالخطة (الجدول) وبالمصروف (التكلفة).","weight":1,"left":[{"id":"a","label":"10 ملايين: كل ما خُطط للمشروع","match":"bac"},{"id":"b","label":"5 ملايين: ما كان يجب إنجازه حتى اليوم","match":"pv"},{"id":"c","label":"4 ملايين: قيمة ما أُنجز فعلًا بأسعار الخطة","match":"ev"},{"id":"d","label":"5 ملايين: ما صُرف فعلًا","match":"ac"}],"right":[{"id":"bac","label":"BAC الميزانية عند الإكمال"},{"id":"pv","label":"PV القيمة المخططة"},{"id":"ev","label":"EV القيمة المكتسبة"},{"id":"ac","label":"AC التكلفة الفعلية"}]},{"type":"choice","title_ar":"ماذا تقول المؤشرات؟","prompt_ar":"احسب مؤشري أداء الجدول (EV ÷ PV) والتكلفة (EV ÷ AC). ما القراءة الصحيحة؟","context_ar":"","why_ar":"مؤشر أقل من 1 يعني أداء أقل من الخطة. والمقارنة بين المصروف والمخطط وحدهما مضللة.","weight":2,"options":[{"id":"both","label":"المؤشران 0.8: متأخر عن الجدول ومتجاوز للتكلفة معًا","score":4,"feedback_ar":"4 ÷ 5 = 0.8 للاثنين: كل ريال صُرف أنتج 0.8 من قيمته، والإنجاز 80% من المخطط.","then_ar":""},{"id":"cost","label":"المشروع في الجدول، والمشكلة في التكلفة فقط","score":1,"feedback_ar":"الإنجاز 4 من 5 مخطط، فالجدول متأخر أيضًا.","then_ar":""},{"id":"fine","label":"المصروف يساوي المخطط (5 = 5)، فالمشروع سليم","score":0,"feedback_ar":"مقارنة المصروف بالمخطط تخفي أن الإنجاز أقل منهما. هذا بالضبط ما تكشفه القيمة المكتسبة.","then_ar":""}]},{"type":"choice","title_ar":"أي تقدير للتكلفة النهائية؟","prompt_ar":"تبيّن أن سبب التجاوز ضعف إنتاجية المورد، ولم يتغير شيء فيه. أي تقدير عند الإكمال أصدق؟","context_ar":"","why_ar":"الصيغة تتبع السبب: الأداء المتكرر يُقسم على المؤشر، والانحراف العارض يُضاف ما بقي بسعر الخطة.","weight":2,"options":[{"id":"cpi","label":"EAC = BAC ÷ CPI = 12.5 مليونًا، لأن الأداء سيستمر كما هو","score":4,"feedback_ar":"السبب متكرر، فالافتراض الصحيح استمرار الأداء.","then_ar":""},{"id":"atypical","label":"EAC = AC + (BAC − EV) = 11 مليونًا، لأن الانحراف عارض","score":1,"feedback_ar":"هذه الصيغة لانحراف عارض لن يتكرر، وسببك هنا قائم.","then_ar":""},{"id":"bac","label":"10 ملايين، فالميزانية لم تتغير","score":0,"feedback_ar":"تجاهل الأداء الفعلي يؤجل المفاجأة إلى الإغلاق.","then_ar":""}]},{"type":"choice","title_ar":"قرار المعلم","prompt_ar":"ماذا تحمل إلى اللجنة غدًا؟","context_ar":"","why_ar":"المعالم جسور قرار لا محطات تقرير.","weight":1,"options":[{"id":"options","label":"التقدير الجديد، وسببه، وخيارين: تغيير المورد أو تقليص النطاق، مع أثر كل منهما على المنافع","score":4,"feedback_ar":"المعلم نقطة قرار: رقم وسبب وخيارات وأثرها على القيمة.","then_ar":""},{"id":"report","label":"تقرير أداء بالمؤشرين دون توصية، والقرار للجنة","score":2,"feedback_ar":"المؤشر بلا خيارات يترك اللجنة تبدأ من الصفر.","then_ar":""},{"id":"hide","label":"تأجيل العرض حتى يتحسن الأداء في الشهر القادم","score":0,"feedback_ar":"الإدارة بالاستثناء تعني رفع الانحراف حين يتجاوز الحدود، لا إخفاءه.","then_ar":""}]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$portfolio-review$x$, $x$scenario$x$, $x$milestone$x$, $x$ch5$x$, 1, $x$intermediate$x$, 15, 50,
  $x$مراجعة المحفظة$x$,
  $x$لجنة المحفظة أمام تخفيض في التمويل: أي المبادرات تستمر، وأيها تُعاد توجيهها، وأيها تُوقف إيقافًا منظمًا.$x$,
  $x${"story_ar":"خفضت الجهة تمويل المحفظة 20% في منتصف العام. أمامك خمس مبادرات، وعليك أن تجهز للجنة توصية بمعايير معلنة لا بحسب نفوذ أصحابها.","role_ar":"مدير مكتب المحفظة في الجهة","closing_ar":"المحفظة تسأل: هل نستثمر في الأشياء الصحيحة؟ والمشروع الناجح في محفظة خاطئة نجاح محلي وخسارة مؤسسية.","meters":[{"id":"value","label":"القيمة الاستراتيجية","start":60},{"id":"trust","label":"ثقة اللجنة","start":50}],"steps":[{"type":"order","title_ar":"دورة المحفظة","prompt_ar":"رتّب دورة المحفظة كما يجب أن تسير.","context_ar":"","why_ar":"الدورة تعود: ما تقرره المراجعة يغذي الاختيار التالي.","weight":1,"items":[{"id":"select","label":"اختيار وتمويل"},{"id":"evaluate","label":"تقييم ومفاضلة بمعايير معلنة"},{"id":"rebalance","label":"مراجعة وتوازن: إيقاف أو إعادة توجيه أو تعزيز"}],"answer":["select","evaluate","rebalance"]},{"type":"allocate","title_ar":"معايير المفاضلة","prompt_ar":"وزّع مئة نقطة على معايير المفاضلة بما يناسب جهة تمر بتخفيض تمويل.","context_ar":"","why_ar":"الأثر الاستراتيجي أولًا، والجاهزية مهمة حين يضيق التمويل لأن المبادرة غير الجاهزة تستهلك دون أن تنتج.","weight":2,"items":[{"id":"impact","label":"الأثر الاستراتيجي"},{"id":"return","label":"العائد"},{"id":"risk","label":"المخاطر"},{"id":"ready","label":"الجاهزية"}],"total":100,"unit_ar":"نقطة","ideal":{"impact":40,"return":25,"risk":15,"ready":20},"tol":10},{"type":"choice","title_ar":"المشروع الناجح في المكان الخاطئ","prompt_ar":"مشروع «بوابة الموردين» يسير على خطته بمؤشرات خضراء، لكنه لم يعد يخدم هدفًا استراتيجيًا بعد دمج الإدارات. صاحبه نافذ ويطالب باستمراره.","context_ar":"","why_ar":"عدد المبادرات الموقفة أو المعاد توجيهها عند معالم المراجعة مؤشر صحة لا فشل.","weight":2,"options":[{"id":"orderly","label":"إيقاف منظم: معلم إغلاق يحفظ ما تحقق، ويوثق الدروس، ويعيد توزيع الفريق بكرامة","score":4,"feedback_ar":"القرار في أعلى طبقة يمسها، والإيقاف المنظم يحفظ القيمة والناس.","then_ar":"","effects":{"value":15,"trust":10}},{"id":"keep","label":"استمراره لأنه ناجح ولا داعي لإغضاب صاحبه","score":0,"feedback_ar":"المحفظة المفتوحة يستمر فيها كل ما يدخل، فتُحسم القرارات بالنفوذ.","then_ar":"","effects":{"value":-15,"trust":-10}},{"id":"cut","label":"إيقافه فورًا وتوزيع ميزانيته غدًا","score":1,"feedback_ar":"الإيقاف دون معلم إغلاق يضيع ما تحقق ويكسر ثقة الفرق.","then_ar":"","effects":{"value":5,"trust":-5}}]},{"type":"choice","title_ar":"التمويل المرحلي","prompt_ar":"مبادرة واعدة لكن جاهزيتها منخفضة تطلب تمويلها كاملًا لثلاث سنوات. ما توصيتك؟","context_ar":"","why_ar":"التمويل المرحلي يجعل كل معلم بوابة استثمار.","weight":1,"options":[{"id":"staged","label":"تمويلها حتى معلمها القادم، والتمويل التالي مشروط بما يثبته المعلم","score":4,"feedback_ar":"يُموّل المشروع حتى معلمه القادم لا حتى نهايته.","then_ar":"","effects":{"value":10,"trust":10}},{"id":"full","label":"تمويلها كاملًا لأنها واعدة","score":1,"feedback_ar":"الوعد ليس دليلًا، والتمويل الكامل يلغي نقطة القرار التالية.","then_ar":"","effects":{"value":-5,"trust":-5}},{"id":"reject","label":"رفضها حتى ترتفع جاهزيتها","score":2,"feedback_ar":"قد تضيع الفرصة؛ التمويل المرحلي يختبرها بكلفة محدودة.","then_ar":"","effects":{"trust":5}}]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
