ير بتغير الموقف.","weight":1,"options":[{"id":"face","label":"تطلب لقاء تعاون على قضية واحدة جوهرية، وتبدأ بفهم موقفه قبل عرض موقفك","score":4,"feedback_ar":"التجنب صالح للتافه أو المؤقت، وتحوله إلى عادة يراكم كلفة لا يراها أحد حتى تنفجر.","then_ar":""},{"id":"escalate","label":"ترفع كل القضايا إلى الراعي دفعة واحدة","score":1,"feedback_ar":"التصعيد الشامل يقفز فوق علاقة ستحتاجها طويلًا.","then_ar":""},{"id":"wait","label":"تنتظر حتى ينتهي المشروع","score":0,"feedback_ar":"القرارات المعلقة هي التي تؤخر المشروع.","then_ar":""}]}]}$x$::jsonb
) on conflict (key) do nothing;

insert into leaders.lab_items (key, kind, dimension, chapter_key, sort, min_level, minutes, points, title_ar, summary_ar, spec) values (
  $x$direct-challenge$x$, $x$scenario$x$, $x$leadership$x$, $x$ch6$x$, 1, $x$advanced$x$, 20, 60,
  $x$تحدٍّ قيادي بأداة DIRECT$x$,
