  $x${"story_ar":"قرار الإدارة العليا: نقل خدمة الشكاوى من الفروع إلى المنصة خلال تسعين يومًا. فريق الفروع قلق على وظائفه، ومدير العمليات يرى القرار متسرعًا، والمستفيدون كبار السن لم يُسألوا.","role_ar":"قائد تحول رقمي في جهة خدمية","closing_ar":"التعاطف حاضر منذ التشخيص، وموضعه في الأداة لحظة تثبيت الحل مع المتأثرين به. والتتبع حتى الإغلاق هو ما يحول القرار إلى أثر.","meters":[{"id":"trust","label":"ثقة الفريق","start":50},{"id":"momentum","label":"زخم التنفيذ","start":50}],"steps":[{"type":"order","title_ar":"خطوات الأداة","prompt_ar":"رتّب خطوات DIRECT.","context_ar":"","why_ar":"ترتيب الأداة منطق التنفيذ، لا ترتيب الأهمية؛ فالتعاطف يرافق التشخيص أيضًا.","weight":1,"items":[{"id":"d","label":"تشخيص"},{"id":"i","label":"تأثير"},{"id":"r","label":"حل"},{"id":"e","label":"تعاطف"},{"id":"c","label":"تواصل"},{"id":"t","label":"تتبع"}],"answer":["d","i","r","e","c","t"]},{"type":"choice","title_ar":"التشخيص","prompt_ar":"بماذا تبدأ؟","context_ar":"","why_ar":"التشخيص يسبق الحركة.","weight":2,"options":[{"id":"listen","label":"جلسات قصيرة مع الفروع ومدير العمليات وعينة من المستفيدين لفهم ما سيخسره كل طرف","score":4,"feedback_ar":"لا يُفهم تحدٍّ دون فهم من يعيشه.","then_ar":"","effects":{"trust":15,"momentum":5}},{"id":"plan","label":"خطة تنفيذ تفصيلية للتسعين يومًا تعرضها غدًا","score":1,"feedback_ar":"خطة قبل الفهم تحل مشكلة غير التي أمامك.","then_ar":"","effects":{"momentum":10,"trust":-10}},{"id":"memo","label":"تعميم يشرح أن القرار نهائي","score":0,"feedback_ar":"التعميم يُسكت القلق ولا يعالجه.","then_ar":"","effects":{"trust":-20}}]},{"type":"choice","title_ar":"التأثير","prompt_ar":"مدير العمليات يملك ما تحتاجه (الفرق والأنظمة)، ولا سلطة لك عليه. كيف تكسبه؟","context_ar":"","why_ar":"من تحتاج كسبه قبل أن تختار الحل.","weight":2,"options":[{"id":"exchange","label":"تفهم ما يهمه (استقرار التشغيل) وتعرض مرحلة تجريبية في فرعين بمؤشرات يختارها هو","score":4,"feedback_ar":"التأثير بلا سلطة يأتي من فهم ما يهم الآخر وما تقدمه له.","then_ar":"","effects":{"momentum":15,"trust":10}},{"id":"escalate","label":"تطلب من الإدارة العليا إلزامه","score":1,"feedback_ar":"الإلزام يكسب الامتثال لا الالتزام.","then_ar":"","effects":{"momentum":5,"trust":-10}},{"id":"bypass","label":"تتجاوزه وتعمل مع فرقه مباشرة","score":0,"feedback_ar":"تجاوز صاحب القرار يصنع خصمًا دائمًا.","then_ar":"","effects":{"trust":-15}}]},{"type":"choice","title_ar":"الحل والتعاطف","prompt_ar":"اخترت النقل المرحلي. ما الذي يثبته مع المتأثرين به؟","context_ar":"","why_ar":"الحل يثبت حين يرى المتأثرون أنفسهم فيه.","weight":1,"options":[{"id":"both","label":"مسار بديل في الفروع لكبار السن، وخطة إعادة تأهيل موظفي الفروع لدعم المنصة","score":4,"feedback_ar":"التعاطف هنا قرار: ما يحتاجه المتأثرون ليتبنوا الحل.","then_ar":"","effects":{"trust":20}},{"id":"words","label":"رسالة تقدير لجهود الفروع","score":1,"feedback_ar":"التقدير دون معالجة الخسارة كلام.","then_ar":"","effects":{"trust":5}},{"id":"none","label":"لا شيء؛ الحل جيد بذاته","score":0,"feedback_ar":"الحل الذي يتجاهل من يخسرون يقاوَم بصمت.","then_ar":"","effects":{"trust":-15,"momentum":-10}}]},{"type":"classify","title_ar":"التواصل والتتبع","prompt_ar":"صنّف كل إجراء: تواصل يبقي الأطراف معك، أم تتبع حتى الإغلاق؟","context_ar":"","why_ar":"التواصل يبقي الناس معك، والتتبع يبقي الأثر حيًا حتى الإغلاق.","weight":1,"bins":[{"id":"comm","label":"تواصل"},{"id":"track","label":"تتبع"}],"items":[{"id":"weekly","label":"تحديث أسبوعي قصير للفروع بما تغير وما لم يتغير","bin":"comm"},{"id":"faq","label":"إجابة مكتوبة عن أسئلة الموظفين المتكررة","bin":"comm"},{"id":"kpi","label":"مؤشر زمن إغلاق الشكوى مقابل خط الأساس كل أسبوعين","bin":"track"},{"id":"gate","label":"معلم مراجعة في اليوم الستين يقرر التوسع أو التعديل","bin":"track"}]}]}$x$::jsonb
) on conflict (key) do nothing;
